      display: inline-block;
      width: 1.25rem;
      height: 1.25rem;
      margin-left: 1rem;
      flex-shrink: 0;
      transition: transform 200ms ease;
      background-color: var(--primary);
      border-radius: 0.25rem;
      position: relative;
    }

    .toggle-icon::before {
      content: '';
      position: absolute;
      width: 0.5rem;
      height: 2px;
      background-color: var(--bg-white);
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
    }

    .toggle-icon::after {
      content: '';
      position: absolute;
      width: 2px;
      height: 0.5rem;
      background-color: var(--bg-white);
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
